import prepared from "./android-release.generated.json";
import type { DownloadArtifact } from "./download-artifact";

// Generated by the byte-verifying build step, before Next compiles the pages.
// Runtime rendering has no filesystem dependency on CDN-only APK files.
export function getPublishedAndroidArtifact(): DownloadArtifact | null {
  return prepared.artifact as DownloadArtifact | null;
}
